#include <utility>
#include <iostream>

int main() {
    // p1.first and p1.second are guaranteed to be zero
    std::pair<int, float> p1;

    // Contrast with indeterminate default initialization
    // int x; // x is indeterminate (garbage)

    std::cout << "P1: " << p1.first << ", " << p1.second << std::endl;

    // Custom type must have default constructor
    struct Data { int val = 10; };
    std::pair<Data, int> p2; // p2.first.val is 10, p2.second is 0
}
